/**
 * 3. SoundScape Audio & Visualizer Controller
 * Manages HTML5 Audio element, AudioContext, AnalyserNode, and Canvas rendering
 */
export class SoundScapePlayer {
  private audio: HTMLAudioElement;
  private audioCtx: AudioContext | null = null;
  private analyser: AnalyserNode | null = null;
  private sourceNode: MediaElementAudioSourceNode | null = null;
  private animFrameId: number | null = null;
  private canvas: HTMLCanvasElement | null = null;

...

constructor(callbacks?: { onStateChange?: (state: PlayerState) => void }) {
    this.onStateChange = callbacks?.onStateChange;

    // Create native audio element with crossOrigin set for Web Audio routing
    this.audio = new Audio();
    this.audio.crossOrigin = 'anonymous';
    this.audio.volume = this.state.volume;

    this.setupAudioListeners();
  }

  private setupAudioListeners() {
    this.audio.addEventListener('timeupdate', () => {
      this.state.currentTime = this.audio.currentTime;
      this.state.duration = this.audio.duration || 30;
      this.emitState();
    });

    this.audio.addEventListener('ended', () => {
      this.state.isPlaying = false;
      this.state.currentTime = 0;
      this.emitState();
    });

    this.audio.addEventListener('error', (e) => {
      console.error('Audio playback error encountered:', e);
      this.state.isPlaying = false;
      this.emitState();
    });

...

private emitState() {
    if (this.onStateChange) {
      this.onStateChange({ ...this.state });
    }
  }

  /**
   * Lazily initialize Web Audio API on first user interaction
   */
  private initAudioPipeline() {
    if (!this.audioCtx) {
      const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
      this.audioCtx = new AudioContextClass();

      this.analyser = this.audioCtx.createAnalyser();
      this.analyser.fftSize = 64; // Yields 32 frequency bins, ideal for spectrum bars

      this.sourceNode = this.audioCtx.createMediaElementSource(this.audio);
      this.sourceNode.connect(this.analyser);
      this.analyser.connect(this.audioCtx.destination);
    }

    if (this.audioCtx.state === 'suspended') {
      this.audioCtx.resume();
    }
  }

  /**
   * Play a track from Deezer
   */
  public async playTrack(track: DeezerTrack) {
    this.initAudioPipeline();

    if (this.state.currentTrack?.id !== track.id) {
      this.state.currentTrack = track;
      this.audio.src = track.preview;
    }

    try {
      await this.audio.play();
      this.state.isPlaying = true;
      this.emitState();
      this.startVisualizer();
    } catch (err) {
      console.error('Playback failed to start:', err);
      this.state.isPlaying = false;
      this.emitState();
    }
  }

