  "description": "A solo duet player. closer plays your Spotify playlist, listens while you sing, and carries the vocals you leave behind.",
  "scripts": {
    "dev": "vite",
    "build": "tsc && vite build",
    "preview": "vite preview"
  },
  "devDependencies": {
    "typescript": "~5.9.3",
    "vite": "^7.1.11"
  }
}

import { defineConfig } from 'vite';

// The dev server binds a fixed loopback port so the Spotify redirect URI
// (http://127.0.0.1:5173/callback) stays stable. Spotify requires an exact
// match with the URI registered in the developer dashboard.
export default defineConfig({
  server: {
    host: '127.0.0.1',
    port: 5173,
    strictPort: true,
  },
  preview: {
    host: '127.0.0.1',
    port: 4173,
    strictPort: true,
  },
});

// Runtime configuration. The Spotify Client ID is not a secret (it is a public
// identifier used with the PKCE flow), but it belongs to the developer's own
// dashboard app, so it is entered once and stored in this browser only.

const CLIENT_ID_KEY = 'closer.clientId';

export function getClientId(): string | null {
  const id = localStorage.getItem(CLIENT_ID_KEY);
  return id && id.trim() ? id.trim() : null;
}

export function setClientId(id: string): void {
  localStorage.setItem(CLIENT_ID_KEY, id.trim());
}

export function clearClientId(): void {
  localStorage.removeItem(CLIENT_ID_KEY);
}

/** The exact redirect URI this app answers on — must be registered in the Spotify dashboard. */
export function redirectUri(): string {
  return `${window.location.origin}/callback`;
}

export const SPOTIFY_SCOPES = [
  'user-read-private',
  'user-modify-playback-state',
  'streaming',
  'playlist-read-private',
  'playlist-read-collaborative',
].join(' ');

// Spotify track and artist names are messy: "Song (feat. X) - Remastered 2011".
// LRCLIB matches much better on a cleaned title and the primary artist.

const DASH_KEYWORDS =
  /(remaster|remaster|version|edit|mix|deluxe|anniversary|bonus|mono|stereo|feat|ft\.?|featuring|single|radio|session|instrumental|karaoke)/i;

export function cleanTitle(raw: string): string {
  let t = raw.trim();
  if (!t) return raw;

  // Remove bracketed annotations like "(feat. Someone)" or "[Live]" or "{...}".
  const bracket = /\s*[([{][^)\]}]*[)\]}]/g;
  let prev = '';
  while (prev !== t) {
    prev = t;
    t = t.replace(bracket, ' ');
  }

  // Drop dash-separated suffixes such as "- 2011 Remaster" / "- Live Version".
  const parts = t.split(/\s+[-–—]\s+/);
  if (parts.length > 1) {
    const kept = parts.filter((p) => !DASH_KEYWORDS.test(p));
    t = kept.length ? kept.join(' - ') : parts[0];
  }

  t = t.replace(/\s+/g, ' ').trim();
  return t || raw.trim();
}

/** Primary artist for lyrics matching ("A feat. B" -> "A", multi-artist lists -> first). */
export function cleanArtist(artists: string[]): string {
  const primary = (artists[0] ?? '').trim();
  if (!primary) return '';
  const cut = primary.split(/\s+(?:feat\.?|ft\.?|featuring|vs\.?)\s+/i)[0];
  return cut.trim() || primary;
}

export function formatMs(ms: number): string {
  if (!Number.isFinite(ms) || ms < 0) ms = 0;
  const total = Math.floor(ms / 1000);
  const m = Math.floor(total / 60);
  const s = total % 60;
  return `${m}:${s.toString().padStart(2, '0')}`;
}

// Authorization Code flow with PKCE, fully client-side.
// Spotify requires: HTTPS redirect URIs (loopback http://127.0.0.1 is allowed),
// an exact redirect URI match, and a S256 code challenge.

import { getClientId, redirectUri, SPOTIFY_SCOPES } from './config';

const TOKEN_URL = 'https://accounts.spotify.com/api/token';
const AUTHORIZE_URL = 'https://accounts.spotify.com/authorize';
const PKCE_KEY = 'closer.pkce';
const TOKENS_KEY = 'closer.tokens';

export interface Tokens {
  accessToken: string;
  refreshToken: string | null;
  /** Unix ms when the access token stops being usable (with safety margin). */
  expiresAt: number;
}

interface PkcePending {
  verifier: string;
  state: string;
}

export class AuthError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'AuthError';
  }
}

function base64url(buffer: ArrayBuffer): string {
  const bytes = new Uint8Array(buffer);
  let str = '';
  for (const b of bytes) str += String.fromCharCode(b);
  return btoa(str).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

function randomString(byteLength: number): string {
  const bytes = new Uint8Array(byteLength);
  crypto.getRandomValues(bytes);
  return base64url(bytes.buffer);
}

export function getTokens(): Tokens | null {
  const raw = localStorage.getItem(TOKENS_KEY);
  if (!raw) return null;
  try {
    const parsed = JSON.parse(raw) as Tokens;
    if (parsed.accessToken && parsed.expiresAt) return parsed;
  } catch {
    /* fall through */
  }
  return null;
}

function saveTokens(tokens: Tokens): void {
  localStorage.setItem(TOKENS_KEY, JSON.stringify(tokens));
}

export function logout(): void {
  localStorage.removeItem(TOKENS_KEY);
  sessionStorage.removeItem(PKCE_KEY);
}

export function isLoggedIn(): boolean {
  return getTokens() !== null;
}

/** Redirect the browser to Spotify's authorize page. */
export async function login(): Promise<void> {
  const clientId = getClientId();
  if (!clientId) throw new AuthError('No Spotify Client ID is configured yet.');

  const verifier = randomString(96);
  const state = randomString(16);
  const hashed = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(verifier));
  const challenge = base64url(hashed);

  sessionStorage.setItem(PKCE_KEY, JSON.stringify({ verifier, state } satisfies PkcePending));

  const params = new URLSearchParams({
    response_type: 'code',
    client_id: clientId,
    scope: SPOTIFY_SCOPES,
    code_challenge_method: 'S256',
    code_challenge: challenge,
    redirect_uri: redirectUri(),
    state,
  });

  window.location.assign(`${AUTHORIZE_URL}?${params.toString()}`);
}

/**
 * If the current URL is the OAuth callback, exchange the code for tokens,
 * clean the URL, and return true. Throws a friendly AuthError when Spotify
 * returned an error or the state check fails.
 */
export async function handleCallbackIfPresent(): Promise<boolean> {
  const url = new URL(window.location.href);
  const code = url.searchParams.get('code');
  const state = url.searchParams.get('state');
  const error = url.searchParams.get('error');
  if (!code && !error) return false;

  const params = new URLSearchParams();
  for (const [k, v] of url.searchParams) params.set(k, v);
  window.history.replaceState({}, '', url.origin + url.pathname);

  if (error) {
    const friendly =
      error === 'access_denied'
        ? 'Authorization was declined. closer needs Spotify access to run your duets.'
        : `Spotify sign-in failed (${error}).`;
    throw new AuthError(friendly);
  }
  if (!code || !state) return false;

  const pendingRaw = sessionStorage.getItem(PKCE_KEY);
  sessionStorage.removeItem(PKCE_KEY);
  const pending: PkcePending | null = pendingRaw ? JSON.parse(pendingRaw) : null;
  if (!pending || pending.state !== state) {
    throw new AuthError('Sign-in could not be verified. Please try connecting again.');
  }

  const clientId = getClientId();
  if (!clientId) throw new AuthError('No Spotify Client ID is configured yet.');

  const body = new URLSearchParams({
    grant_type: 'authorization_code',
    code,
    redirect_uri: redirectUri(),
    client_id: clientId,
    code_verifier: pending.verifier,
  });

  const res = await fetch(TOKEN_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: body.toString(),
  });

  if (!res.ok) {
    const detail = await res.text();
    throw new AuthError(`Spotify rejected the sign-in (${res.status}). ${detail.slice(0, 200)}`);
  }

  const data = (await res.json()) as {
    access_token: string;
    expires_in: number;
    refresh_token?: string;
  };

  const previous = getTokens();
  saveTokens({
    accessToken: data.access_token,
    refreshToken: data.refresh_token ?? previous?.refreshToken ?? null,
    expiresAt: Date.now() + (data.expires_in - 60) * 1000,
  });
  return true;
}

/** Returns a valid access token, refreshing silently when needed. */
export async function ensureToken(): Promise<string> {
  const tokens = getTokens();
  if (tokens && Date.now() < tokens.expiresAt) return tokens.accessToken;
  if (!tokens?.refreshToken) {
    logout();
    throw new AuthError('Your Spotify session has ended. Please connect again.');
  }

  const clientId = getClientId();
  if (!clientId) throw new AuthError('No Spotify Client ID is configured.');

  const body = new URLSearchParams({
    grant_type: 'refresh_token',
    refresh_token: tokens.refreshToken,
    client_id: clientId,
  });

  const res = await fetch(TOKEN_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: body.toString(),
  });

  if (!res.ok) {
    logout();
    throw new AuthError('Your Spotify session has expired. Please connect again.');
  }

  const data = (await res.json()) as {
    access_token: string;
    expires_in: number;
    refresh_token?: string;
  };

  saveTokens({
    accessToken: data.access_token,
    refreshToken: data.refresh_token ?? tokens.refreshToken,
    expiresAt: Date.now() + (data.expires_in - 60) * 1000,
  });
  return data.access_token;
}

// Thin wrapper over the Spotify Web API. Only endpoints that remain available
// to new apps are used (audio-features / audio-analysis / recommendations are
// deprecated for new apps and are deliberately avoided).

import { ensureToken, isLoggedIn } from './auth';

const API = 'https://api.spotify.com/v1';

export class ApiError extends Error {
  status: number;
  constructor(message: string, status: number) {
    super(message);
    this.name = 'ApiError';
    this.status = status;
  }
}

async function request<T>(path: string, init?: RequestInit, retry = true): Promise<T> {
  if (!isLoggedIn()) throw new ApiError('Not connected to Spotify.', 401);
  const token = await ensureToken();
  const res = await fetch(`${API}${path}`, {
    ...init,
    headers: {
      Authorization: `Bearer ${token}`,
      ...(init?.body ? { 'Content-Type': 'application/json' } : {}),
    },
  });

  if (res.status === 401 && retry) return request<T>(path, init, false);

  if (res.status === 204) return undefined as T;

  if (!res.ok) {
    let message = `Spotify request failed (${res.status}).`;
    try {
      const data = (await res.json()) as { error?: { message?: string } };
      if (data.error?.message) message = data.error.message;
    } catch {
      /* keep generic message */
    }
    throw new ApiError(message, res.status);
  }

  return (await res.json()) as T;
}

export interface Me {
  id: string;
  display_name: string | null;
  product: string;
  images: { url: string }[];
}

export interface Playlist {
  id: string;
  uri: string;
  name: string;
  images: { url: string }[];
  tracks: { total: number };
  owner: { display_name: string | null };
}

export interface Track {
  id: string | null;
  uri: string | null;
  name: string;
  duration_ms: number;
  artists: { name: string }[];
  album: { name: string; images: { url: string }[] };
}

interface Paged<T> {
  items: T[];
  next: string | null;
  total: number;
}

export async function getMe(): Promise<Me> {
  return request<Me>('/me');
}

/** All playlists the user follows or owns, following pagination. */
export async function getPlaylists(): Promise<Playlist[]> {
  const out: Playlist[] = [];
  let path = '/me/playlists?limit=50';
  for (let page = 0; page < 20 && path; page++) {
    const res = await request<Paged<{ track?: Playlist }>>(path);
    for (const item of res.items) {
      // Local files show up as items without a track object.
      if (item.track) out.push(item.track);
    }
    path = res.next ? `${res.next.replace(API, '')}` : '';
  }
  return out;
}

export interface PlaylistDetail {
  id: string;
  uri: string;
  name: string;
  images: { url: string }[];
  tracks: { total: number };
}

export async function getPlaylistDetail(id: string): Promise<PlaylistDetail> {
  return request<PlaylistDetail>(`/playlists/${id}?fields=id,uri,name,images,tracks(total)`);
}

/** All playable tracks of a playlist, following pagination. */
export async function getPlaylistTracks(id: string): Promise<Track[]> {
  const out: Track[] = [];
  let path = `/playlists/${id}/tracks?limit=50`;
  for (let page = 0; page < 40 && path; page++) {
    const res = await request<Paged<{ track: Track | null }>>(path);
    for (const item of res.items) {
      const t = item.track;
      if (t && t.uri && t.uri.startsWith('spotify:track:')) out.push(t);
    }
    path = res.next ? `${res.next.replace(API, '')}` : '';
  }
  return out;
}

export async function searchTracks(query: string): Promise<Track[]> {
  if (!query.trim()) return [];
  const res = await request<{ tracks: Paged<Track> }>(
    `/search?type=track&limit=24&q=${encodeURIComponent(query.trim())}`,
  );
  return res.tracks.items.filter((t) => t.uri);
}

/** Start playback of a playlist (optionally at a given track) on the given device. */
export async function startPlaylist(
  deviceId: string,
  playlistUri: string,
  trackUri?: string,
): Promise<void> {
  const body: Record<string, unknown> = { context_uri: playlistUri, position_ms: 0 };
  if (trackUri) body.offset = { uri: trackUri };
  await request(`/me/player/play?device_id=${encodeURIComponent(deviceId)}`, {
    method: 'PUT',
    body: JSON.stringify(body),
  });
}

/** Start playback of loose tracks (e.g. search results) on the given device. */
export async function startTracks(deviceId: string, uris: string[]): Promise<void> {
  await request(`/me/player/play?device_id=${encodeURIComponent(deviceId)}`, {
    method: 'PUT',
    body: JSON.stringify({ uris, position_ms: 0 }),
  });
}

export async function transferPlayback(deviceId: string, play: boolean): Promise<void> {
  await request('/me/player', {
    method: 'PUT',
    body: JSON.stringify({ device_ids: [deviceId], play }),
  });
}

// Wrapper around the Spotify Web Playback SDK.
// The SDK turns this browser into a Spotify Connect device. Playback audio
// lives inside the SDK's own cross-origin (DRM) iframe and cannot be tapped
// into the Web Audio API — so the duet engine controls playback through the
// SDK's official volume/transport methods only.

import { ensureToken } from './auth';

const SDK_URL = 'https://sdk.scdn.co/spotify-player.js';

export interface SdkTrack {
  uri: string;
  id: string | null;
  name: string;
  artists: { name: string; uri: string }[];
  album: { name: string; images: { url: string }[] };
  duration_ms?: number;
}

export interface PlaybackState {
  position: number;
  duration: number;
  paused: boolean;
  /** performance.now() timestamp matching `position`. */
  updatedAt: number;
  track: SdkTrack;
  nextTracks: SdkTrack[];
}

interface SpotifyPlayerLike {
  connect(): Promise<boolean>;
  disconnect(): void;
  addListener(event: string, cb: (payload: never) => void): boolean;
  activateElement(): Promise<void>;
  togglePlay(): Promise<void>;
  pause(): Promise<void>;
  resume(): Promise<void>;
  seek(ms: number): Promise<void>;
  nextTrack(): Promise<void>;
  previousTrack(): Promise<void>;
  setVolume(v: number): Promise<void>;
  getVolume(): Promise<number>;
  getCurrentState(): Promise<unknown>;
}

interface SpotifyNamespace {
  Player: new (options: {
    name: string;
    volume?: number;
    getOAuthToken: (cb: (token: string) => void) => void;
  }) => SpotifyPlayerLike;
}

declare global {
  interface Window {
    Spotify?: SpotifyNamespace;
    onSpotifyWebPlaybackSDKReady?: () => void;
  }
}

export class SdkError extends Error {
  kind: 'init' | 'auth' | 'account' | 'playback';
  constructor(kind: SdkError['kind'], message: string) {
    super(message);
    this.name = 'SdkError';
    this.kind = kind;
  }
}

let loadPromise: Promise<SpotifyNamespace> | null = null;

function loadSdk(): Promise<SpotifyNamespace> {
  if (loadPromise) return loadPromise;
  loadPromise = new Promise((resolve, reject) => {
    if (window.Spotify) {
      resolve(window.Spotify);
      return;
    }
    window.onSpotifyWebPlaybackSDKReady = () => {
      if (window.Spotify) resolve(window.Spotify);
      else reject(new SdkError('init', 'Spotify SDK loaded without an API.'));
    };
    const script = document.createElement('script');
    script.src = SDK_URL;
    script.async = true;
    script.onerror = () => reject(new SdkError('init', 'Could not load the Spotify SDK. Check your connection or extensions.'));
    document.head.appendChild(script);
  });
  return loadPromise;
}

export class PlayerBridge {
  private player: SpotifyPlayerLike | null = null;
  private deviceId: string | null = null;

  onState: ((state: PlaybackState) => void) | null = null;
  onError: ((error: SdkError) => void) | null = null;
  onDeviceReady: (() => void) | null = null;
  onDeviceLost: (() => void) | null = null;

  /** Load the SDK, create the player and connect. Resolves with the device id. */
  async connect(): Promise<string> {
    if (this.deviceId && this.player) return this.deviceId;
    const Spotify = await loadSdk();

    const player = new Spotify.Player({
      name: 'closer — web player',
      getOAuthToken: (cb) => {
        ensureToken().then(cb).catch(() => {
          this.onError?.(new SdkError('auth', 'Spotify session ended. Please reconnect.'));
        });
      },
      volume: 1,
    });

    player.addListener('ready', ((payload: { device_id: string }) => {
      this.deviceId = payload.device_id;
      this.onDeviceReady?.();
    }) as never);

    player.addListener('not_ready', (() => {
      this.onDeviceLost?.();
    }) as never);

    player.addListener('player_state_changed', ((state: {
      position: number;
      duration: number;
      paused: boolean;
      track_window: { current_track: SdkTrack; next_tracks: SdkTrack[] };
    } | null) => {
      if (!state) return;
      const playback: PlaybackState = {
        position: state.position,
        duration: state.duration,
        paused: state.paused,
        updatedAt: performance.now(),
        track: state.track_window.current_track,
        nextTracks: state.track_window.next_tracks,
      };
      this.onState?.(playback);
    }) as never);

    const errorMap: Record<string, SdkError['kind']> = {
      initialization_error: 'init',
      authentication_error: 'auth',
      account_error: 'account',
      playback_error: 'playback',
    };
    for (const [event, kind] of Object.entries(errorMap)) {
      player.addListener(event, ((e: { message: string }) => {
        const message =
          kind === 'account'
            ? 'Spotify Premium is required for in-browser playback.'
            : e.message || 'Spotify playback reported an error.';
        this.onError?.(new SdkError(kind, message));
      }) as never);
    }

    const success = await player.connect();
    if (!success) throw new SdkError('init', 'Could not connect to Spotify playback.');

    this.player = player;

    const deviceId = await new Promise<string>((resolve, reject) => {
      if (this.deviceId) {
        resolve(this.deviceId);
        return;
      }
      const timeout = window.setTimeout(() => {
        reject(new SdkError('init', 'Spotify playback took too long to become ready. Try again.'));
      }, 20000);
      this.onDeviceReady = () => {
        window.clearTimeout(timeout);
        this.onDeviceReady = null;
        if (this.deviceId) resolve(this.deviceId);
      };
    });

    return deviceId;
  }

  /** Must be called synchronously inside a user gesture on iOS Safari. */
  activate(): void {
    void this.player?.activateElement();
  }

  async togglePlay(): Promise<void> {
    await this.player?.togglePlay();
  }

  async pause(): Promise<void> {
    await this.player?.pause();
  }

  async resume(): Promise<void> {
    await this.player?.resume();
  }

  async seek(ms: number): Promise<void> {
    await this.player?.seek(Math.max(0, Math.round(ms)));
  }

  async next(): Promise<void> {
    await this.player?.nextTrack();
  }

  async previous(): Promise<void> {
    await this.player?.previousTrack();
  }

  async setVolume(v: number): Promise<void> {
    await this.player?.setVolume(Math.min(1, Math.max(0, v)));
  }

  disconnect(): void {
    try {
      this.player?.disconnect();
    } catch {
      /* already gone */
    }
    this.player = null;
    this.deviceId = null;
  }
}

// LRCLIB (https://lrclib.net) — a free, open lyrics database with a
// CORS-enabled API that needs no key. Used for time-synced karaoke lyrics.
// The client identifies itself via the Lrclib-Client header (browser JS cannot
// set the User-Agent header) and honors Retry-After on 429/503.

import { cleanArtist, cleanTitle } from './clean';

const BASE = 'https://lrclib.net';
const CLIENT_IDENTITY = 'closer 0.1.0 (local personal duet player)';

export interface LyricLine {
  /** Seconds from the start of the track. */
  time: number;
  text: string;
}

export interface Lyrics {
  synced: LyricLine[] | null;
  plain: string | null;
}

interface LrcRecord {
  trackName: string;
  artistName: string;
  albumName: string;
  duration: number;
  instrumental: boolean;
  plainLyrics: string | null;
  syncedLyrics: string | null;
}

const cache = new Map<string, Lyrics>();

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

async function lrcFetch(path: string): Promise<Response | null> {
  const res = await fetch(`${BASE}${path}`, {
    headers: { 'Lrclib-Client': CLIENT_IDENTITY, 'X-User-Agent': CLIENT_IDENTITY },
  });
  if (res.ok) return res;
  if (res.status === 429 || res.status === 503) {
    const retry = Number(res.headers.get('Retry-After') ?? '2');
    await sleep(Math.min(10, Math.max(1, retry)) * 1000);
    const second = await fetch(`${BASE}${path}`, {
      headers: { 'Lrclib-Client': CLIENT_IDENTITY, 'X-User-Agent': CLIENT_IDENTITY },
    });
    if (second.ok) return second;
  }
  // 404 (no record) and other failures simply mean "no lyrics".
  return null;
}

/** Parse an LRC document: `[mm:ss.xx] line` (multiple stamps per line allowed). */
export function parseLrc(text: string): LyricLine[] {
  const out: LyricLine[] = [];
  const stamp = /\[(\d{1,3}):(\d{2})(?:[.:](\d{1,3}))?\]/g;
  for (const raw of text.split(/\r?\n/)) {
    stamp.lastIndex = 0;
    const times: number[] = [];
    let match: RegExpExecArray | null;
    while ((match = stamp.exec(raw)) !== null) {
      const minutes = Number(match[1]);
      const seconds = Number(match[2]);
      const fraction = match[3] ? Number(match[3].padEnd(3, '0').slice(0, 3)) : 0;
      times.push(minutes * 60 + seconds + fraction / 1000);
    }
    if (!times.length) continue;
    const line = raw.slice(stamp.lastIndex).trim();
    for (const time of times) out.push({ time, text: line });
  }
  out.sort((a, b) => a.time - b.time);
  return out;
}

function recordToLyrics(record: LrcRecord): Lyrics {
  const synced = record.syncedLyrics ? parseLrc(record.syncedLyrics) : null;
  return {
    synced: synced && synced.length ? synced : null,
    plain: record.plainLyrics ?? null,
  };
}

/**
 * Fetch lyrics for a Spotify track. Tries the exact-match endpoint first
 * (with duration, which improves matching), then a fuzzy search.
 */
export async function fetchLyrics(
  trackName: string,
  artists: string[],
  albumName: string,
  durationMs: number,
): Promise<Lyrics> {
  const title = cleanTitle(trackName);
  const artist = cleanArtist(artists);
  const key = `${title}::${artist}`;
  const cached = cache.get(key);
  if (cached) return cached;

  const headers = { 'Lrclib-Client': CLIENT_IDENTITY, 'X-User-Agent': CLIENT_IDENTITY };
  const duration = Math.round(durationMs / 1000);

  let lyrics: Lyrics = { synced: null, plain: null };

  if (title && artist) {
    const exactPath =
      `/api/get?track_name=${encodeURIComponent(title)}` +
      `&artist_name=${encodeURIComponent(artist)}` +
      `&album_name=${encodeURIComponent(albumName)}` +
      (duration >= 1 && duration <= 3600 ? `&duration=${duration}` : '');
    const res = await fetch(`${BASE}${exactPath}`, { headers });
    if (res.ok) {
      lyrics = recordToLyrics((await res.json()) as LrcRecord);
    } else if (res.status === 429 || res.status === 503) {
      const retry = Number(res.headers.get('Retry-After') ?? '2');
      await sleep(Math.min(10, Math.max(1, retry)) * 1000);
      const second = await fetch(`${BASE}${exactPath}`, { headers });
      if (second.ok) lyrics = recordToLyrics((await second.json()) as LrcRecord);
    }

    if (!lyrics.synced && !lyrics.plain) {
      const searchRes = await lrcFetch(
        `/api/search?track_name=${encodeURIComponent(title)}&artist_name=${encodeURIComponent(artist)}`,
      );
      if (searchRes) {
        const records = (await searchRes.json()) as LrcRecord[];
        const withSync = records.filter((r) => r.syncedLyrics);
        const withPlain = records.filter((r) => r.plainLyrics && !r.instrumental);
        const pickClosest = (pool: LrcRecord[]): LrcRecord | undefined =>
          pool
            .slice()
            .sort(
              (a, b) =>
                Math.abs((a.duration - duration)) - Math.abs((b.duration - duration)),
            )[0];
        const best = pickClosest(withSync) ?? pickClosest(withPlain);
        if (best) lyrics = recordToLyrics(best);
      }
    }
  }

  cache.set(key, lyrics);
  return lyrics;
}

/** Index of the active line for a playback position (-1 before the first line). */
export function activeLineIndex(lines: LyricLine[], positionSec: number): number {
  let lo = 0;
  let hi = lines.length - 1;
  let idx = -1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (lines[mid].time <= positionSec) {
      idx = mid;
      lo = mid + 1;
    } else {
      hi = mid - 1;
    }
  }
  return idx;
}

// Microphone monitor: listens through getUserMedia, measures loudness and
// spectral balance, and decides whether the user is singing right now.
//
// Chrome's echo cancellation (enabled here) uses the tab's own audio output as
// a far-end reference, which substantially suppresses the song playing through
// the Web Playback SDK — leaving mostly the user's voice. Headphones make this
// perfect; without them the sensitivity slider helps.

export interface MicState {
  /** Smoothed input level, 0..1, for the meter. */
  level: number;
  /** True while the detector considers the user to be singing (with hold-over). */
  voiced: boolean;
  /** Detected fundamental frequency when voiced, else null. */
  pitchHz: number | null;
}

const NOTE_NAMES = ['C', 'C♯', 'D', 'D♯', 'E', 'F', 'F♯', 'G', 'G♯', 'A', 'A♯', 'B'];

export function describePitch(hz: number): string {
  const midi = 69 + 12 * Math.log2(hz / 440);
  const rounded = Math.round(midi);
  const name = NOTE_NAMES[((rounded % 12) + 12) % 12];
  const octave = Math.floor(rounded / 12) - 1;
  return `${name}${octave} · ${Math.round(hz)} Hz`;
}

export class MicMonitor {
  onState: ((state: MicState) => void) | null = null;

  private ctx: AudioContext | null = null;
  private stream: MediaStream | null = null;
  private analyser: AnalyserNode | null = null;
  private raf = 0;
  private frame = 0;
  private timeBuf: Float32Array = new Float32Array(0);
  private freqBuf: Uint8Array = new Uint8Array(0);

  /** Room noise level captured during calibration. */
  noiseFloor = 0.008;
  /** 0.5 = stricter, 2 = picks up quiet singers more readily. */
  sensitivity = 1;

  private lastVoiceAt = 0;
  private voiced = false;
  private level = 0;
  private pitchHz: number | null = null;
  private calibrating = false;

  get running(): boolean {
    return this.ctx !== null;
  }

  async start(): Promise<void> {
    if (this.ctx) return;
    this.stream = await navigator.mediaDevices.getUserMedia({
      audio: {
        echoCancellation: true,
        noiseSuppression: true,
        autoGainControl: true,
      },
    });
    const ctx = new AudioContext();
    this.ctx = ctx;
    const source = ctx.createMediaStreamSource(this.stream);
    const analyser = ctx.createAnalyser();
    analyser.fftSize = 2048;
    analyser.smoothingTimeConstant = 0.6;
    source.connect(analyser);
    this.analyser = analyser;
    this.timeBuf = new Float32Array(analyser.fftSize);
    this.freqBuf = new Uint8Array(analyser.frequencyBinCount);
    await ctx.resume();
    this.loop();
  }

  stop(): void {
    cancelAnimationFrame(this.raf);
    this.raf = 0;
    this.stream?.getTracks().forEach((t) => t.stop());
    void this.ctx?.close();
    this.stream = null;
    this.ctx = null;
    this.analyser = null;
    this.voiced = false;
    this.level = 0;
    this.pitchHz = null;
  }

  /** Sample the room for a moment to establish the noise floor. Call while quiet. */
  async calibrate(ms = 1600): Promise<void> {
    if (!this.ctx) throw new Error('Start the microphone before calibrating.');
    this.calibrating = true;
    const samples: number[] = [];
    const started = performance.now();
    while (performance.now() - started < ms) {
      samples.push(this.rawRms());
      await sleep(25);
    }
    this.calibrating = false;
    samples.sort((a, b) => a - b);
    if (samples.length) {
      // A quiet percentile is more robust than the mean against one-off bumps.
      this.noiseFloor = Math.max(0.002, samples[Math.floor(samples.length * 0.25)]);
    }
  }

  private rawRms(): number {
    if (!this.analyser) return 0;
    this.analyser.getFloatTimeDomainData(this.timeBuf);
    let sum = 0;
    for (const x of this.timeBuf) sum += x * x;
    return Math.sqrt(sum / this.timeBuf.length);
  }

  private loop(): void {
    const ctx = this.ctx;
    const analyser = this.analyser;
    if (!ctx || !analyser) return;
    this.raf = requestAnimationFrame(() => this.loop());
    if (this.calibrating) return;

    this.frame++;
    const rms = this.rawRms();
    analyser.getByteFrequencyData(this.freqBuf);

    // Voice band ratio: singing lives mostly between ~250 Hz and ~3.4 kHz.
    const binHz = ctx.sampleRate / analyser.fftSize;
    const lowBin = Math.max(1, Math.floor(250 / binHz));
    const voiceTopBin = Math.min(this.freqBuf.length - 1, Math.ceil(3400 / binHz));
    const allTopBin = Math.min(this.freqBuf.length - 1, Math.ceil(12000 / binHz));
    let voiceEnergy = 0;
    for (let i = lowBin; i <= voiceTopBin; i++) voiceEnergy += this.freqBuf[i] ** 2;
    let allEnergy = 0;
    for (let i = lowBin; i <= allTopBin; i++) allEnergy += this.freqBuf[i] ** 2;
    const ratio = allEnergy > 0 ? voiceEnergy / allEnergy : 0;

    // Detector with hold-over: quick to engage, slower to release.
    const threshold = Math.max(this.noiseFloor * 3.2, 0.011) / this.sensitivity;
    const now = performance.now();
    if (rms > threshold && ratio > 0.4) {
      this.lastVoiceAt = now;
    }
    this.voiced = now - this.lastVoiceAt < 650 && rms > threshold * 0.4;

    // Meter: perceptual-ish mapping of rms to 0..1.
    const target = Math.min(1, Math.pow(rms / 0.22, 0.6));
    this.level += (target - this.level) * 0.35;

    if (this.voiced && this.frame % 4 === 0) {
      this.pitchHz = detectPitch(this.timeBuf, ctx.sampleRate);
    } else if (!this.voiced) {
      this.pitchHz = null;
    }

    this.onState?.({ level: this.level, voiced: this.voiced, pitchHz: this.pitchHz });
  }
}

/**
 * Bounded normalized autocorrelation pitch detector (70 Hz – 1 kHz).
 * Runs on a decimated copy of the frame to stay cheap.
 */
function detectPitch(buf: Float32Array, sampleRate: number): number | null {
  const decimation = 2;
  const sr = sampleRate / decimation;
  const n = Math.floor(buf.length / decimation);
  if (n < 256) return null;

  const x = new Float32Array(n);
  for (let i = 0; i < n; i++) x[i] = buf[i * decimation];

  let rms = 0;
  for (const v of x) rms += v * v;
  rms = Math.sqrt(rms / n);
  if (rms < 0.01) return null;

  const minLag = Math.max(2, Math.floor(sr / 1000));
  const maxLag = Math.min(n - 256, Math.ceil(sr / 70));
  let bestLag = -1;
  let bestVal = 0;

  for (let lag = minLag; lag <= maxLag; lag++) {
    let sum = 0;
    let energyA = 0;
    let energyB = 0;
    for (let i = 0; i + lag < n; i++) {
      sum += x[i] * x[i + lag];
      energyA += x[i] * x[i];
      energyB += x[i + lag] * x[i + lag];
    }
    const norm = Math.sqrt(energyA * energyB);
    const value = norm > 0 ? sum / norm : 0;
    if (value > bestVal) {
      bestVal = value;
      bestLag = lag;
    }
  }

  if (bestLag > 0 && bestVal > 0.55) return sr / bestLag;
  return null;
}

// The duet engine — the heart of closer.
//
// Spotify's playback stream cannot be DSP-processed (it runs inside the SDK's
// cross-origin DRM iframe, and Spotify requires content "in its original
// form"). So the duet is driven by the SDK's official volume control:
//
//   - while the mic hears you singing  ->  the artist ducks to a backing level
//   - when you stop                    ->  the artist comes back and sings
//
// Manual mode lets you hold a button (or the space bar) to take the lead,
// which is reliable even on speakers instead of headphones.

import type { PlayerBridge } from './sdk';
import type { MicMonitor } from './mic';

export type DuetMode = 'auto' | 'manual';
export type Lead = 'artist' | 'you';

const TICK_MS = 80;
const APPROACH = 0.28; // per-tick approach factor; ~250 ms to converge

export class DuetEngine {
  private player: PlayerBridge | null = null;
  private mic: MicMonitor | null = null;
  private timer = 0;
  private current = 1;
  private lastSent = 1;
  private manualHeld = false;

  mode: DuetMode = 'auto';
  lead: Lead = 'artist';
  /** Master volume 0..1 (what the artist plays at when you are not singing). */
  baseVolume = 1;
  /** Fraction of the master volume while you sing (0..1). */
  backingFactor = 0.12;

  onLead: ((lead: Lead) => void) | null = null;

  start(player: PlayerBridge, mic: MicMonitor): void {
    this.player = player;
    this.mic = mic;
    this.current = this.baseVolume;
    this.lastSent = -1;
    if (this.timer) window.clearInterval(this.timer);
    this.timer = window.setInterval(() => this.tick(), TICK_MS);
  }

  stop(): void {
    if (this.timer) window.clearInterval(this.timer);
    this.timer = 0;
    void this.player?.setVolume(this.baseVolume);
  }

  setMode(mode: DuetMode): void {
    this.mode = mode;
    if (mode === 'auto') this.manualHeld = false;
  }

  setManualHeld(held: boolean): void {
    if (this.mode !== 'manual') return;
    this.manualHeld = held;
  }

  setBaseVolume(v: number): void {
    this.baseVolume = Math.min(1, Math.max(0, v));
  }

  setBackingFactor(f: number): void {
    this.backingFactor = Math.min(1, Math.max(0, f));
  }

  isSinging(): boolean {
    if (this.mode === 'manual') return this.manualHeld;
    return this.mic?.onState ? this.micSinging : false;
  }

  private micSinging = false;

  /** Mic monitor feeds us its state; the tick loop samples it. */
  setMicVoiced(voiced: boolean): void {
    this.micSinging = voiced;
  }

  private tick(): void {
    if (!this.player) return;
    const singing = this.mode === 'manual' ? this.manualHeld : this.micSinging;
    const nextLead: Lead = singing ? 'you' : 'artist';
    if (nextLead !== this.lead) {
      this.lead = nextLead;
      this.onLead?.(nextLead);
    }
    const target = singing ? this.baseVolume * this.backingFactor : this.baseVolume;
    this.current += (target - this.current) * APPROACH;
    if (Math.abs(target - this.current) < 0.004) this.current = target;
    if (Math.abs(this.current - this.lastSent) > 0.004) {
      this.lastSent = this.current;
      void this.player.setVolume(Math.min(1, Math.max(0, this.current)));
    }
  }
}

