/* ============================================================
   closer — design system
   Adapted from the LoreSign design language: calm editorial
   surfaces, Sora for display, Urbanist for reading, one blue
   family for actions, 8px radii, thin rules, restrained motion.
   ============================================================ */

:root {
  --font-sora: 'Sora', sans-serif;
  --font-urbanist: 'Urbanist', sans-serif;

  --bg: #ffffff;
  --surface-2: #f7f7f7;
  --fg: #1a1a1a;
  --fg-muted: #4b5563;
  --fg-subtle: #666666;
  --fg-faint: #717171;

  --accent: #1457ff;
  --accent-hover: #0b46d8;
  --accent-tint: #f5f7ff;
  --accent-soft: #6a95ff;

  --border: #e6e6e6;
  --border-strong: #d9d9d9;
  --border-control: #949494;

  --radius: 8px;

  --dark: #1a1a1a;
  --dark-body: rgba(255, 255, 255, 0.8);
  --dark-muted: #9ca3af;
  --dark-border: rgba(255, 255, 255, 0.14);

  --shadow-cta: 0 10px 24px rgba(20, 87, 255, 0.28), inset 0 -1px 0 rgba(255, 255, 255, 0.22);
  --shadow-soft: 0 1px 3px rgba(26, 26, 26, 0.06);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-urbanist);
  font-size: 16px;
  line-height: 1.6;
  color: var(--fg);
  background: var(--bg);
  -webkit-font-smoothing: antialiased;
}

img {
  display: block;
  max-width: 100%;
}

a {
  color: var(--accent);
  text-decoration: none;
}

button {
  font: inherit;
  color: inherit;
  background: none;
  border: none;
  cursor: pointer;
}

input {
  font: inherit;
}

:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
  border-radius: var(--radius);
}

.container {
  max-width: 1120px;
  margin: 0 auto;
  padding-left: 24px;
  padding-right: 24px;
}

.container.narrow {
  max-width: 760px;
}

/* ------------------------------------------------------------
   Typography
   ------------------------------------------------------------ */

h1 {
  font-family: var(--font-sora);
  font-weight: 600;
  font-size: clamp(28px, 6vw, 46px);
  line-height: 1.25;
  letter-spacing: -0.01em;
}

h2 {
  font-family: var(--font-sora);
  font-weight: 600;
  font-size: clamp(24px, 4vw, 32px);
  line-height: 1.2;
}

h3 {
  font-family: var(--font-sora);
  font-weight: 600;
  font-size: 18px;
  line-height: 1.3;
}

.lede {
  font-size: 18px;
  line-height: 1.6;
  color: var(--fg-muted);
  max-width: 60ch;
}

.muted {
  color: var(--fg-subtle);
  font-size: 14px;
}

code {
  font-family: ui-monospace, 'Cascadia Code', Consolas, monospace;
  font-size: 0.9em;
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 2px 8px;
  word-break: break-all;
}

/* ------------------------------------------------------------
   Navigation
   ------------------------------------------------------------ */

.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 50;
  background: var(--bg);
  border-bottom: 1px solid var(--border);
}

.nav-inner {
  max-width: 1300px;
  margin: 0 auto;
  padding: 0 24px;
  height: 64px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.brand {
  font-family: var(--font-sora);
  font-weight: 600;
  font-size: 18px;
  color: var(--fg);
  letter-spacing: -0.01em;
}

.brand-dot {
  color: var(--accent);
}

.nav-links {
  display: flex;
  gap: 28px;
}

.nav-links a {
  font-size: 14px;
  font-weight: 500;
  color: var(--fg-subtle);
  transition: color 0.2s ease;
  padding: 8px 0;
}

.nav-links a:hover,
.nav-links a.active {
  color: var(--fg);
}

.nav-user {
  display: flex;
  align-items: center;
  gap: 12px;
}

.user-chip {
  display: flex;
  align-items: center;
  gap: 10px;
}

.avatar {
  width: 30px;
  height: 30px;
  border-radius: 50%;
  object-fit: cover;
}

.avatar-fallback {
  width: 30px;
  height: 30px;
  border-radius: 50%;
  background: var(--accent-tint);
  color: var(--accent);
  font-size: 13px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
}

.user-name {
  font-size: 14px;
  font-weight: 600;
}

.plan-badge {
  font-size: 12px;
  font-weight: 600;
  color: var(--fg-faint);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 3px 8px;
  white-space: nowrap;
}

/* ------------------------------------------------------------
   Buttons
   ------------------------------------------------------------ */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  height: 44px;
  padding: 0 20px;
  border-radius: var(--radius);
  border: 1px solid var(--border-strong);
  background: var(--bg);
  color: var(--accent);
  font-size: 14px;
  font-weight: 600;
  white-space: nowrap;
  transition: background 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease;
}

.btn:hover {
  background: var(--surface-2);
  border-color: var(--border-control);
}

.btn-neutral {
  color: var(--fg);
}

.btn-ghost {
  border-color: transparent;
  color: var(--accent);
}

.btn-ghost:hover {
  border-color: transparent;
  background: var(--surface-2);
}

.btn-primary {
  height: 54px;
  padding: 0 28px;
  font-size: 16px;
  color: #ffffff;
  background: linear-gradient(180deg, var(--accent-soft) 0%, var(--accent) 100%);
  border: none;
  box-shadow: var(--shadow-cta);
  transition: box-shadow 0.25s ease, transform 0.25s ease, filter 0.25s ease;
}

.btn-primary:hover {
  filter: brightness(1.05);
  transform: translateY(-1px);
  box-shadow: 0 14px 30px rgba(20, 87, 255, 0.32), inset 0 -1px 0 rgba(255, 255, 255, 0.22);
}

.btn-primary:active {
  transform: translateY(0);
}

.btn-small {
  height: 36px;
  padding: 0 16px;
  font-size: 13px;
}

.btn:disabled,
.btn-primary:disabled {
  background: var(--surface-2);
  color: var(--fg-faint);
  border-color: var(--border);
  box-shadow: none;
  cursor: not-allowed;
  transform: none;
  filter: none;
}

.btn[aria-pressed='true'] {
  background: var(--accent-tint);
  border-color: var(--accent);
}

/* ------------------------------------------------------------
   Forms
   ------------------------------------------------------------ */

.field {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.field label {
  font-size: 13px;
  font-weight: 600;
  color: var(--fg-subtle);
}

.input {
  height: 44px;
  padding: 0 14px;
  border: 1px solid var(--border-control);
  border-radius: var(--radius);
  font-size: 15px;
  color: var(--fg);
  background: var(--bg);
  width: 100%;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.input::placeholder {
  color: var(--fg-faint);
}

.input:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(20, 87, 255, 0.15);
}

/* ------------------------------------------------------------
   Hero / connect screen
   ------------------------------------------------------------ */

.hero {
  padding: 112px 0 64px;
  text-align: center;
}

.hero h1 {
  margin-bottom: 16px;
}

.hero .lede {
  margin: 0 auto 32px;
}

.cta-row {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}

.steps {
  list-style: none;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 56px;
  text-align: left;
}

.steps li {
  border-top: 1px solid var(--border);
  padding-top: 18px;
}

.step-k {
  display: block;
  font-family: var(--font-sora);
  font-weight: 600;
  font-size: 13px;
  color: var(--accent);
  margin-bottom: 6px;
}

.steps p {
  font-size: 15px;
  color: var(--fg-muted);
  line-height: 1.55;
}

.note-card {
  margin: 48px auto 0;
  max-width: 720px;
  text-align: left;
  background: var(--accent-tint);
  border: 1px solid #d3deff;
  border-radius: var(--radius);
  padding: 18px 24px;
}

.note-card p {
  font-size: 14px;
  color: var(--fg);
  line-height: 1.6;
}

.note-card p + p {
  margin-top: 8px;
}

.setup-card {
  margin: 48px auto 0;
  max-width: 720px;
  text-align: left;
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow-soft);
  padding: 32px;
}

.setup-card h2 {
  font-size: 22px;
  margin-bottom: 8px;
}

.setup-card > p {
  font-size: 15px;
  color: var(--fg-muted);
