// Small DOM helpers shared by every screen.

export type Attrs = Record<string, string | number | boolean | ((e: Event) => void)>;

export function el<K extends keyof HTMLElementTagNameMap>(
  tag: K,
  attrs?: Attrs | null,
  ...children: (Node | string | number | null | undefined)[]
): HTMLElementTagNameMap[K] {
  const node = document.createElement(tag);
  if (attrs) {
    for (const [key, value] of Object.entries(attrs)) {
      if (value === false || value == null) continue;
      if (typeof value === 'function') {
        node.addEventListener(key.startsWith('on') ? key.slice(2) : key, value as EventListener);
      } else if (value === true) {
        node.setAttribute(key, '');
      } else {
        node.setAttribute(key, String(value));
      }
    }
  }
  for (const child of children) {
    if (child == null) continue;
    node.append(child instanceof Node ? child : document.createTextNode(String(child)));
  }
  return node;
}

/** Real artwork from Spotify, or a labelled placeholder block when there is none. */
export function artwork(
  images: { url: string }[] | undefined,
  cls: string,
  alt: string,
  label = 'No artwork',
): HTMLElement {
  const url = images?.[0]?.url;
  if (url) {
    const img = el('img', { class: cls, src: url, alt, loading: 'lazy' });
    img.addEventListener('error', () => {
      const fallback = el('div', { class: `${cls} art-fallback` }, label);
      img.replaceWith(fallback);
    });
    return img;
  }
  return el('div', { class: `${cls} art-fallback` }, label);
}

/** Real avatar image, or a placeholder circle with the user's initial. */
export function avatar(images: { url: string }[] | undefined, name: string): HTMLElement {
  const url = images?.[0]?.url;
  if (url) return el('img', { class: 'avatar', src: url, alt: '' });
  const initial = (name || 'L').trim().charAt(0).toUpperCase() || 'L';
  return el('span', { class: 'avatar-fallback', 'aria-hidden': 'true' }, initial);
}

export function toast(message: string, kind: 'info' | 'error' = 'info'): void {
  const root = document.getElementById('toast-root');
  if (!root) return;
  const node = el('div', { class: `toast${kind === 'error' ? ' error' : ''}`, role: 'status' }, message);
  root.append(node);
  window.setTimeout(() => node.remove(), 6000);
}

export function formatTime(sec: number): string {
  if (!Number.isFinite(sec) || sec < 0) sec = 0;
  const total = Math.floor(sec);
  const m = Math.floor(total / 60);
  const s = total % 60;
  return `${m}:${s.toString().padStart(2, '0')}`;
}

// Shared session state across screens.

import type { Me, Playlist, PlaylistDetail, Track } from './lib/api';
import type { PlayerBridge } from './lib/sdk';
import type { MicMonitor } from './lib/mic';
import type { DuetEngine } from './lib/duet';

export interface RoomContext {
  kind: 'playlist' | 'loose';
  playlistUri?: string;
  playlistName?: string;
  startTrackUri?: string;
  looseUris?: string[];
  initialTrack: Track;
}

export interface Prefs {
  baseVolume: number;
  backingFactor: number;
  sensitivity: number;
  mode: 'auto' | 'manual';
}

const PREFS_KEY = 'closer.prefs';

export function loadPrefs(): Prefs {
  try {
    const raw = localStorage.getItem(PREFS_KEY);
    if (raw) {
      const p = JSON.parse(raw) as Prefs;
      return {
        baseVolume: clamp01(p.baseVolume ?? 1),
        backingFactor: clamp01(p.backingFactor ?? 0.12),
        sensitivity: Math.min(2, Math.max(0.5, p.sensitivity ?? 1)),
        mode: p.mode === 'manual' ? 'manual' : 'auto',
      };
    }
  } catch {
    /* defaults below */
  }
  return { baseVolume: 1, backingFactor: 0.12, sensitivity: 1, mode: 'auto' };
}

export function savePrefs(prefs: Prefs): void {
  localStorage.setItem(PREFS_KEY, JSON.stringify(prefs));
}

function clamp01(v: number): number {
  return Math.min(1, Math.max(0, Number.isFinite(v) ? v : 0));
}

