function shell(active: 'library' | 'tracks', content: HTMLElement, dark = false): void {
  const me = store.me;
  document.body.style.background = dark ? '#1a1a1a' : '';
  app.replaceChildren(
    el(
      'header',
      { class: 'nav' },
      el(
        'div',
        { class: 'nav-inner' },
        el('a', { class: 'brand', href: '#', onclick: (e) => { e.preventDefault(); goLibrary(); } },
          'closer', el('span', { class: 'brand-dot' }, '.')),
        el(
          'div',
          { class: 'nav-user' },
          me
            ? el(
                'div',
                { class: 'user-chip' },
                avatar(me.images, me.display_name ?? me.id),
                el('span', { class: 'user-name' }, me.display_name ?? me.id),
                el(
                  'span',
                  { class: 'plan-badge' },
                  me.product === 'premium' ? 'Premium' : me.product === 'open' ? 'Free plan' : me.product,
                ),
              )
            : null,
          isLoggedIn()
            ? el('button', {
                class: 'btn btn-small',
                onclick: () => {
                  logout();
                  location.reload();
                },
              }, 'Log out')
            : null,
        ),
      ),
    ),
    content,
    el(
      'footer',
      { class: 'footer' },
      el(
        'div',
        { class: 'footer-inner' },
        el('span', {}, 'closer — a personal duet player. Spotify playback requires Premium. Lyrics come from LRCLIB.'),
        el('span', {}, el('a', { href: 'https://developer.spotify.com/dashboard', target: '_blank', rel: 'noopener' }, 'Spotify for Developers')),
      ),
    ),
  );
}

/* ------------------------------------------------------------
   Connect screen
   ------------------------------------------------------------ */

export function renderConnectScreen(error?: string): void {
  document.body.style.background = '';
  const clientId = getClientId();

  const content = el(
    'main',
    { class: 'hero' },
    el(
      'div',
      { class: 'container narrow' },
      el('h1', {}, 'Sing with your playlist. The other half is on closer.'),
      el(
        'p',
        { class: 'lede' },
        'closer plays songs from your Spotify playlists, listens while you sing, and carries every part you leave behind. When your voice drops, the original vocals pick the song straight back up — a duet, solo.',
      ),
      error ? el('p', { class: 'form-error' }, error) : null,
      el('div', { class: 'cta-row', id: 'cta' }, clientId ? null : setupCard()),
      clientId
        ? el(
            'div',
            { class: 'cta-row' },
            el('button', {
              class: 'btn btn-primary',
              onclick: async (e) => {
                const btn = e.currentTarget as HTMLButtonElement;
                btn.disabled = true;
                btn.textContent = 'Opening Spotify…';
                try {
                  await login();
                } catch (err) {
                  toast(err instanceof Error ? err.message : 'Could not start sign-in.', 'error');
                  btn.disabled = false;
                  btn.textContent = 'Connect Spotify';
                }
              },
            }, 'Connect Spotify'),
            el('button', { class: 'btn', onclick: () => renderConnectScreen() }, 'Change Client ID'),
          )
        : null,
      el(
        'ul',
        { class: 'steps' },
        el('li', {}, el('span', { class: 'step-k' }, '01'), el('p', {}, 'Connect your Spotify account — your playlists load straight into the library.')),
        el('li', {}, el('span', { class: 'step-k' }, '02'), el('p', {}, 'Pick a song. The artist starts singing through your browser as a Spotify Connect device.')),
        el('li', {}, el('span', { class: 'step-k' }, '03'), el('p', {}, 'Start singing. closer hears your voice and ducks the artist so you take the lead; stop, and closer carries the vocals again.')),
      ),
      el(
        'div',
        { class: 'note-card' },
        el('p', {}, 'Wear headphones for the most reliable duet — the app separates your voice from the song using echo cancellation. On speakers, switch the room to Manual mode and hold the lead button (or the space bar) while you sing.'),
        el('p', {}, 'Spotify in-browser playback requires a Premium subscription. Your account is checked automatically when you connect.'),
      ),
    ),
  );
  shellConnect(content);
}

function shellConnect(content: HTMLElement): void {
  document.body.style.background = '';
  app.replaceChildren(
    el(
      'header',
      { class: 'nav' },
      el(
        'div',
        { class: 'nav-inner' },
        el('span', { class: 'brand' }, 'closer', el('span', { class: 'brand-dot' }, '.')),
        el('div', { class: 'nav-user' }),
      ),
    ),
    content,
    el(
      'footer',
      { class: 'footer' },
      el(
        'div',
        { class: 'footer-inner' },
        el('span', {}, 'closer — a personal duet player. Spotify playback requires Premium. Lyrics come from LRCLIB.'),
      ),
    ),
  );
}

function setupCard(): HTMLElement {
  const input = el('input', {
    class: 'input',
    type: 'text',
    id: 'client-id',
    placeholder: 'e.g. 4c1f2a9b8d7e4f3a9b8c7d6e5f4a3b2c',
    autocomplete: 'off',
    spellcheck: 'false',
  }) as HTMLInputElement;
  const error = el('p', { class: 'form-error', hidden: 'true' });

  return el(
    'div',
    { class: 'setup-card' },
    el('h2', {}, 'First, point closer at your Spotify app'),
    el(
      'p',
      {},
      'Create (or reuse) an app in the Spotify developer dashboard, then paste its Client ID below. This takes about two minutes.',
    ),
    el(
      'ol',
      { class: 'setup-ol' },
      el('li', {}, 'Open the ', el('a', { href: 'https://developer.spotify.com/dashboard', target: '_blank', rel: 'noopener' }, 'Spotify developer dashboard'), ' and create an app (any name — “closer” works).'),
      el('li', {}, 'In the app settings, add this exact redirect URI: ', el('code', {}, redirectUri())),
      el('li', {}, 'Under “User Management”, add the email address of the Spotify account you will sing with — development apps can only be used by added users.'),
      el('li', {}, 'Copy the app’s Client ID into the field below and connect.'),
    ),
    el(
      'form',
      {
        class: 'setup-form',
        onsubmit: (e) => {
          e.preventDefault();
          const value = input.value.trim();
          if (!/^[0-9a-f]{32}$/i.test(value)) {
            error.hidden = false;
            error.textContent = 'That does not look like a Spotify Client ID — it is a 32-character hexadecimal string from your dashboard app settings.';
            return;
          }
          error.hidden = true;
          setClientId(value);
          renderConnectScreen();
        },
      },
      el('div', { class: 'field' }, el('label', { for: 'client-id' }, 'Spotify Client ID'), input, error),
      el('button', { class: 'btn btn-primary', type: 'submit' }, 'Save and continue'),
    ),
  );
}

/* ------------------------------------------------------------
   Library screen — playlists + song search
   ------------------------------------------------------------ */

export async function goLibrary(): Promise<void> {
  leaveRoomIfActive();
  renderLibraryScreen();

  try {
    if (!store.playlists.length) store.playlists = await getPlaylists();
    refreshLibraryLists();
  } catch (err) {
    toast(err instanceof Error ? err.message : 'Could not load your playlists.', 'error');
  }
}

export function renderLibraryScreen(): void {
  const content = el(
    'main',
    { class: 'page' },
    el(
      'div',
      { class: 'container' },
      el(
        'div',
        { class: 'page-head' },
        el('h2', {}, 'Your playlists'),
        el('span', { class: 'muted', id: 'library-count' }, 'Loading playlists…'),
      ),
      el(
        'div',
        { class: 'search-row' },
        el('input', {
          class: 'input',
          id: 'library-search',
          type: 'search',
          placeholder: 'Filter playlists, or search songs to sing',
          oninput: () => refreshLibraryLists(),
        }),
        el(
          'div',
          { class: 'segmented', role: 'tablist' },
          el('button', { class: 'seg-btn active', 'data-scope': 'playlists', onclick: () => setScope('playlists') }, 'Playlists'),
          el('button', { class: 'seg-btn', 'data-scope': 'songs', onclick: () => setScope('songs') }, 'Songs'),
        ),
      ),
      el('div', { id: 'library-results' }, el('div', { class: 'empty-state' }, el('h3', {}, 'Loading your playlists…'))),
    ),
  );
  shell('library', content);

  const search = document.getElementById('library-search') as HTMLInputElement;
  let debounce = 0;
  search.addEventListener('input', () => {
    window.clearTimeout(debounce);
    debounce = window.setTimeout(() => void maybeSearchSongs(), 350);
  });
  refreshLibraryLists();
}

let scope: 'playlists' | 'songs' = 'playlists';
let songResults: Track[] = [];
let lastQuery = '';

function setScope(next: 'playlists' | 'songs'): void {
  scope = next;
  for (const btn of document.querySelectorAll('.seg-btn')) {
    btn.classList.toggle('active', (btn as HTMLElement).dataset.scope === scope);
  }
  refreshLibraryLists();
  void maybeSearchSongs();
}

function refreshLibraryLists(): void {
  const results = document.getElementById('library-results');
  const count = document.getElementById('library-count');
  if (!results) return;
  const search = (document.getElementById('library-search') as HTMLInputElement | null)?.value ?? '';
  const query = search.trim().toLowerCase();

  if (scope === 'playlists') {
    const list = store.playlists;
    if (count) count.textContent = list.length ? `${list.length} playlists` : '';
    if (!list.length) {
      results.replaceChildren(
        el(
          'div',
          { class: 'empty-state' },
          el('h3', {}, 'No playlists to sing with yet'),
          el('p', {}, 'Create a playlist in Spotify (or follow one), then come back — it will appear here.'),
        ),
      );
      return;
    }
    const filtered = query ? list.filter((p) => p.name.toLowerCase().includes(query)) : list;
    results.replaceChildren(
      el(
        'div',
        { class: 'playlist-grid' },
        filtered.map((p) => playlistCard(p)),
      ),
      filtered.length
        ? null
        : el('div', { class: 'empty-state' }, el('h3', {}, 'No playlist matches that filter')),
    );
  } else {
    if (count) count.textContent = 'Search songs across all of Spotify';
    if (!songResults.length) {
      results.replaceChildren(
        el(
          'div',
          { class: 'empty-state' },
          el('h3', {}, 'Search for a song to sing'),
          el('p', {}, 'Type a song name and press enter — results stream straight from Spotify.'),
        ),
      );
    } else {
      results.replaceChildren(trackList(songResults, 'loose'));
    }
  }
}

function playlistCard(playlist: Playlist): HTMLElement {
  return el(
    'button',
    {
      class: 'playlist-card',
      onclick: () => void goTracks(playlist.id),
    },
    artwork(playlist.images, 'playlist-art', `Artwork for ${playlist.name}`),
    el(
      'div',
      { class: 'playlist-card-body' },
      el('h3', {}, playlist.name),
      el('div', { class: 'meta' }, `${playlist.tracks.total} songs`),
    ),
  );
}

async function maybeSearchSongs(): Promise<void> {
  const input = document.getElementById('library-search') as HTMLInputElement | null;
  if (!input || scope !== 'songs') return;
  const query = input.value.trim();
  if (!query) {
    songResults = [];
    refreshLibraryLists();
    return;
  }
  if (query === lastQuery) return;
  lastQuery = query;
  try {
    const results = await searchTracks(query);
    if (query !== input.value.trim()) return; // stale response
    songResults = results;
    refreshLibraryLists();
  } catch (err) {
    toast(err instanceof Error ? err.message : 'Song search failed.', 'error');
  }
}

/* ------------------------------------------------------------
   Playlist tracks screen
   ------------------------------------------------------------ */

export async function goTracks(playlistId: string): Promise<void> {
  leaveRoomIfActive();
  renderTracksScreen(null, []);
  try {
    const [detail, tracks] = await Promise.all([getPlaylistDetail(playlistId), getPlaylistTracks(playlistId)]);
    store.playlist = detail;
    store.playlistTracks = tracks;
    renderTracksScreen(detail, tracks);
  } catch (err) {
    toast(err instanceof Error ? err.message : 'Could not load that playlist.', 'error');
    await goLibrary();
  }
}

function renderTracksScreen(
  detail: { name: string; images: { url: string }[]; tracks: { total: number } } | null,
  tracks: Track[],
): void {
  const content = el(
    'main',
    { class: 'page' },
    el(
      'div',
      { class: 'container' },
      el('a', { class: 'back-link', href: '#', onclick: (e) => { e.preventDefault(); void goLibrary(); } }, '← All playlists'),
      detail
        ? el(
            'div',
            { class: 'playlist-head' },
            artwork(detail.images, '', `Artwork for ${detail.name}`),
            el(
              'div',
              {},
              el('h2', {}, detail.name),
              el('p', { class: 'muted' }, `${detail.tracks.total} songs`),
            ),
          )
        : el('div', { class: 'empty-state' }, el('h3', {}, 'Loading playlist…')),
      detail
        ? premiumBanner()
        : null,
      detail ? (tracks.length ? trackList(tracks, 'playlist') : el('div', { class: 'empty-state' }, el('h3', {}, 'This playlist has no playable songs'), el('p', {}, 'Local files and podcast episodes cannot be played through the web player.'))) : null,
    ),
  );
  shell('tracks', content);
}

function premiumBanner(): HTMLElement | null {
  const product = store.me?.product;
  if (product === 'premium') return null;
  return el(
    'div',
    { class: 'banner banner-warn' },
    el('span', {}, 'Spotify Premium is required for in-browser playback. Browsing works without it, but “Sing” needs Premium on the connected account.'),
  );
}

function trackList(tracks: Track[], kind: 'playlist' | 'loose'): HTMLElement {
  return el(
    'div',
    { class: 'track-list' },
    tracks.map((track, index) =>
      el(
        'div',
        { class: 'track-row' },
        kind === 'playlist' ? el('span', { class: 'track-idx' }, String(index + 1)) : el('span', {}),
        artwork(track.album?.images, 'track-thumb', `Artwork for ${track.name}`, '—'),
        el(
          'div',
          { class: 'track-main' },
          el('div', { class: 'track-name' }, track.name),
          el('div', { class: 'track-artists' }, track.artists.map((a) => a.name).join(', ')),
        ),
        el('span', { class: 'track-duration' }, formatMs(track.duration_ms)),
        el(
          'button',
          {
            class: 'btn btn-small btn-neutral',
            onclick: (e) => void startDuet(track, kind === 'playlist', e.currentTarget as HTMLButtonElement),
          },
          'Sing',
        ),
      ),
    ),
  );
}

/* ------------------------------------------------------------
   Starting a duet
   ------------------------------------------------------------ */

async function startDuet(track: Track, fromPlaylist: boolean, button: HTMLButtonElement): Promise<void> {
  if (store.me && store.me.product !== 'premium') {
    toast('Spotify Premium is required for in-browser playback. Connect a Premium account to sing.', 'error');
    return;
  }
  button.disabled = true;
  button.textContent = 'Preparing…';
  const context: RoomContext = fromPlaylist
    ? {
        kind: 'playlist',
        playlistUri: store.playlist?.uri,
        playlistName: store.playlist?.name,
        startTrackUri: track.uri ?? undefined,
        initialTrack: track,
      }
    : { kind: 'loose', looseUris: [track.uri ?? ''], initialTrack: track };
  renderRoom(context);
}

export function leaveRoomIfActive(): void {
  if (store.roomActive) {
    store.roomActive = false;
    store.duet?.stop();
    store.mic?.stop();
    document.removeEventListener('keydown', keyHandler);
    document.removeEventListener('keyup', keyHandler);
  }
}

let keyHandler: ((e: KeyboardEvent) => void) | null = null;
export function setKeyHandler(handler: ((e: KeyboardEvent) => void) | null): void {
  if (keyHandler) {
    document.removeEventListener('keydown', keyHandler);
    document.removeEventListener('keyup', keyHandler);
  }
  keyHandler = handler;
  if (keyHandler) {
    document.addEventListener('keydown', keyHandler);
    document.addEventListener('keyup', keyHandler);
  }
}

export function clearClientIdAndRestart(): void {
  clearClientId();
  renderConnectScreen();
}

content.text:
Now room.ts — the heart of the UI. Careful implementation:

```ts
import { el, artwork, toast, formatTime } from './dom';
import { store, type RoomContext, savePrefs } from './store';
import { PlayerBridge, type PlaybackState } from './lib/sdk';
import { MicMonitor, describePitch } from './lib/mic';
import { DuetEngine, type Lead } from './lib/duet';
import { fetchLyrics, activeLineIndex, type Lyrics } from './lib/lrclib';
import { startPlaylist, startTracks, transferPlayback } from './lib/api';
import { leaveRoomIfActive, setKeyHandler } from './ui'; // circular — room imported by ui. Avoid!
```

Circular: ui.ts imports renderRoom from room.ts; room.ts importing leaveRoomIfActive from ui.ts creates a cycle. Break it: move leaveRoomIfActive + setKeyHandler to store.ts? They touch DOM listeners... put them in room.ts itself and have ui.ts call `room.closeRoom()`? ui.ts imports room already (for renderRoom). So room.ts exports closeRoom() and ui.ts imports it — no cycle. And room.ts must NOT import ui.ts. main.ts imports ui only; room is imported by ui. Key handler: room.ts sets its own listeners and removes on close.

So in room.ts:
```ts
export function closeRoom(): void { ... } // used by exit button and ui.leaveRoomIfActive
```
ui.leaveRoomIfActive calls room.closeRoom(). Update ui.ts accordingly (I wrote leaveRoomIfActive with setKeyHandler logic inside ui; need to change: leaveRoomIfActive → import { closeRoom } from './room'; leaveRoomIfActive() { if (store.roomActive) closeRoom(); } — wait closeRoom itself does the work + goLibrary? Exit button in room calls closeRoom() then goLibrary() (ui). But closeRoom is in room.ts which can't import goLibrary from ui... The exit flow: room's exit button → closeRoom() (stops mic/duet/keys) → then call a callback to navigate. Room can invoke `onExit` passed from ui? renderRoom is called by ui.startDuet — ui can pass exit handler: renderRoom(ctx, {onExit: () => void goLibrary()}). And ui.goLibrary/goTracks call leaveRoomIfActive → closeRoom() without navigation. 

Implement: room.ts exports renderRoom(ctx, onExit) and closeRoom(). ui.ts: import { renderRoom, closeRoom } from './room'; leaveRoomIfActive(): if (store.roomActive) closeRoom(); startDuet: renderRoom(context, () => void goLibrary());

Rewrite relevant ui.ts parts after writing room.ts.

room.ts structure:

```ts
export function renderRoom(ctx: RoomContext, onExit: () => void): void {
  store.roomActive = true;
  const refs = buildRoomDom(ctx, onExit); // returns refs
  void initRoom(ctx, refs);
}

export function closeRoom(): void {
  store.roomActive = false;
  stopTicker...
}
```

State module-level in room.ts:
```ts
let playback: PlaybackState | null = null;
let lyrics: Lyrics | null = null;
let lyricsToken = 0;
let attributions = new Map<number, Lead>();
let counts = { you: 0, artist: 0 };
let lastActive = -2;
let raf = 0;
let ctx: RoomContext | null = null;
let refs: RoomRefs | null = null;
```

buildRoomDom: constructs room layout and returns refs {statusChip, statusDot, statusText, lyricsPanel, lyricsScroll, lyricsEmpty, meterFill, pitch, posTime, durTime, progressFill, progress, playBtn, statsEl, modeSeg buttons, sliders...}

initRoom:
1. ensure player: if (!store.player) store.player = new PlayerBridge(); player.onState = handlePlayerState; player.onError = handleSdkError; deviceId = await player.connect(); catch → status error + toast.
2. mic: if (!store.mic) store.mic = new MicMonitor(); mic.onState = handleMicState; try await mic.start() catch → micAvailable=false; note in room: "Microphone unavailable — Automatic detection is off. Switch to Manual and hold the lead button." (real error state).
3. duet: if (!store.duet) duet = new DuetEngine(); apply prefs; duet.start(player, mic) if mic available else duet.start(player, dummy?) — engine requires mic only for auto mode. If mic unavailable, force mode manual: duet.setMode('manual'), disable auto seg button. duet.start(player, mic!) — pass mic even if not started (micSinging stays false; auto mode disabled anyway). OK.
4. Start playback: try {
    if (ctx.kind === 'playlist' && ctx.playlistUri) await startPlaylist(deviceId, ctx.playlistUri, ctx.startTrackUri);
    else await startTracks(deviceId, ctx.looseUris.filter(Boolean));
   } catch (err) {
     if (err instanceof ApiError && (err.status === 404 || err.status === 403)) { try transfer then play again } else toast + status error.
   }
   Also call player.activate() before starting (must be in user gesture — renderRoom is called synchronously from click handler startDuet! renderRoom → build DOM → initRoom async. player.activate() must happen synchronously in the click. So call player.activate() in startDuet before renderRoom? player may not exist yet on first click. Order: in startDuet, if store.player exists → activate. For first time, connect happens async — REST-triggered play might be blocked? EME autoplay: Chrome usually allows if there was user activation recently (activation lasts ~5s in Chrome? user activation is transient ~ few seconds). REST play → server tells SDK to load → usually within activation window. Tutorials do exactly this; accept + handle 'autoplay_failed' event? The SDK doesn't expose that event name in docs I read — there IS an autoplay_failed event per docs. Add listener: on autoplay_failed → status "Press Play to start". Our play button calls player.resume() from a user gesture → works. I'll wire: SdkError playback 'autoplay_failed'... SDK event name 'autoplay_failed' — add in sdk.ts error map? It's not an error object with message; payload null. Handle separately: player.addListener('autoplay_failed', () => onState with paused true?) Simplest: in handleSdkError unknown kinds ignore; add dedicated listener in sdk.ts calling onError with kind 'playback' and message 'The browser blocked automatic playback. Press Play to start the song.' Let me add that to sdk.ts after.
5. fetch lyrics for initial track (from ctx.initialTrack) — but better to wait for player_state_changed to get real track (SDK gives accurate name/duration). Do both: render initial track info from ctx; when state arrives, if track.uri changed → update + refetch lyrics.
6. ticker rAF: updateUI() every frame.

handlePlayerState(playback):
```ts
roomPlayback = state;
if (currentTrackUri !== state.track.uri) { currentTrackUri = state.track.uri; attributions.clear(); counts reset; lastActive = -2; renderTrackInfo(state.track); void loadLyrics(state.track); }
update play button label; status chip.
```

Ticker update():
```ts
if (!roomPlayback) return;
const pos = roomPlayback.paused ? roomPlayback.position : Math.min(roomPlayback.duration, roomPlayback.position + (performance.now() - roomPlayback.updatedAt));
update time labels, progress fill width %.
if (lyrics?.synced) { idx = activeLineIndex(lyrics.synced, pos/1000); if (idx !== lastActive) { lastActive = idx; applyActive(idx); } }
```

applyActive(idx): for each line element i: classes: active if i===idx; sung if i<idx; remove active/sung else. Attribution: if idx>=0 && !attributions.has(idx) { const lead = duet.lead; attributions.set(idx, lead); counts[lead]++; update chip "who" element on that line } ; stats update; scrollIntoView active.

Attribution display: each line element contains optional span.who appended at render time hidden? Simpler: line divs created once with just text; when attributing, insert span before text. Store refs lines: {el, textSpan}.

loadLyrics(track):
```ts
const token = ++lyricsToken;
setLyricsState('loading');
try {
  const res = await fetchLyrics(track.name, track.artists.map(a=>a.name), track.album.name, track.duration_ms ?? from state);
  if (token !== lyricsToken) return;
  lyrics = res; lastActive = -2; renderLyrics();
} catch { lyrics = null; renderLyrics('error') }
```
renderLyrics: if synced → build line divs (with data-idx), clear attributions; else if plain → plain-lyrics pre; else empty state message:
- "No lyrics found for this track" + p "closer will still duck for you while you sing — the words just won't be shown."

handleMicState(state): meterFill.style.width = `${state.level*100}%`; pitch text = state.voiced && state.pitchHz ? describePitch : '—' (or 'listening'); duet.setMicVoiced(state.voiced).

Status chip update function updateStatus():
```ts
const paused = roomPlayback?.paused ?? true;
if (paused) { dot class paused; text 'Paused'; }
else if (duet?.lead === 'you') { dot you; text 'Your turn — mic is live'; }
else { dot default; text 'closer is singing'; }
```
Call from duet.onLead and play state changes and ticker? onLead + state changes enough; also mic silenced transitions update lead via engine.onLead. Good.

Controls:
- playBtn: onclick → player.togglePlay(); label updated in state handler. Initial label 'Pause' (once playback starts) — before playback starts, button disabled until first state.
- next/prev buttons: player.next()/previous().
- progress click: seek.
- exit: closeRoom() + onExit().
