input.content:
/* ============================================================
   Solo — Spotify-inspired design system
   Dark canvas (#121212), one green family (#1DB954 / #1ED760),
   pill controls, Circular-style single-family type (Figtree),
   art-derived gradient headers, restrained motion.
   ============================================================ */

:root {
  --font: 'Figtree', 'Circular', sans-serif;

  --bg: #121212;
  --surface: #181818;
  --surface-2: #242424;
  --surface-3: #2a2a2a;
  --surface-hover: #1f1f1f;

  --fg: #ffffff;
  --fg-muted: #b3b3b3;
  --fg-faint: #6a6a6a;

  --green: #1db954;
  --green-bright: #1ed760;
  --green-tint: rgba(30, 215, 96, 0.14);

  --border: rgba(255, 255, 255, 0.08);
  --border-strong: rgba(255, 255, 255, 0.3);

  --radius: 8px;
  --pill: 500px;

  --shadow-card: 0 8px 24px rgba(0, 0, 0, 0.5);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font);
  font-size: 16px;
  line-height: 1.6;
  color: var(--fg);
  background: var(--bg);
  -webkit-font-smoothing: antialiased;
}

img {
  display: block;
  max-width: 100%;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font: inherit;
  color: inherit;
  background: none;
  border: none;
  cursor: pointer;
}

input {
  font: inherit;
}

::selection {
  background: var(--green-bright);
  color: #000;
}

:focus-visible {
  outline: 3px solid var(--green-bright);
  outline-offset: 2px;
  border-radius: var(--radius);
}

.container {
  max-width: 1120px;
  margin: 0 auto;
  padding-left: 24px;
  padding-right: 24px;
}

.container.narrow {
  max-width: 760px;
}

/* ------------------------------------------------------------
   Typography
   ------------------------------------------------------------ */

h1 {
  font-weight: 800;
  font-size: clamp(30px, 6vw, 52px);
  line-height: 1.14;
  letter-spacing: -0.02em;
}

h2 {
  font-weight: 700;
  font-size: clamp(24px, 4vw, 34px);
  line-height: 1.2;
  letter-spacing: -0.01em;
}

h3 {
  font-weight: 700;
  font-size: 18px;
  line-height: 1.3;
}

.lede {
  font-size: 18px;
  line-height: 1.65;
  color: var(--fg-muted);
  max-width: 60ch;
}

.muted {
  color: var(--fg-muted);
  font-size: 14px;
}

code {
  font-family: ui-monospace, 'Cascadia Code', Consolas, monospace;
  font-size: 0.88em;
  background: var(--surface-3);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 2px 8px;
  color: var(--fg);
  word-break: break-all;
}

/* ------------------------------------------------------------
   Navigation
   ------------------------------------------------------------ */

.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 50;
  background: rgba(18, 18, 18, 0.92);
  backdrop-filter: blur(8px);
  border-bottom: 1px solid var(--border);
}

.nav-inner {
  max-width: 1300px;
  margin: 0 auto;
  padding: 0 24px;
  height: 64px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.brand {
  font-weight: 800;
  font-size: 20px;
  letter-spacing: -0.02em;
  color: var(--fg);
}

.brand-dot {
  color: var(--green-bright);
}

.nav-user {
  display: flex;
  align-items: center;
  gap: 12px;
}

.user-chip {
  display: flex;
  align-items: center;
  gap: 10px;
}

.avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  object-fit: cover;
}

.avatar-fallback {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: var(--green-bright);
  color: #000;
  font-size: 13px;
  font-weight: 800;
  display: flex;
  align-items: center;
  justify-content: center;
}

.user-name {
  font-size: 14px;
  font-weight: 600;
}

.plan-badge {
  font-size: 12px;
  font-weight: 600;
  color: var(--fg-muted);
  border: 1px solid var(--border-strong);
  border-radius: var(--pill);
  padding: 3px 10px;
  white-space: nowrap;
}

/* ------------------------------------------------------------
   Buttons — Spotify pills
   ------------------------------------------------------------ */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  height: 44px;
  padding: 0 22px;
  border-radius: var(--pill);
  border: 1px solid var(--border-strong);
  background: transparent;
  color: var(--fg);
  font-size: 14px;
  font-weight: 700;
  white-space: nowrap;
  transition: background 0.2s ease, border-color 0.2s ease, transform 0.2s ease;
}

.btn:hover {
  background: rgba(255, 255, 255, 0.12);
  border-color: var(--fg);
}

.btn-neutral {
  color: var(--fg);
}

.btn-ghost {
  border-color: transparent;
  color: var(--fg-muted);
}

.btn-ghost:hover {
  border-color: transparent;
  background: rgba(255, 255, 255, 0.12);
  color: var(--fg);
}

.btn-primary {
  height: 50px;
  padding: 0 30px;
  font-size: 15px;
  color: #000;
  background: var(--green);
  border: none;
  transition: background 0.2s ease, transform 0.2s ease;
}

.btn-primary:hover {
  background: var(--green-bright);
  transform: scale(1.03);
}

.btn-primary:active {
  transform: scale(1);
}

.btn-small {
  height: 36px;
  padding: 0 18px;
  font-size: 13px;
}

.btn:disabled,
.btn-primary:disabled {
  background: var(--surface-3);
  color: var(--fg-faint);
  border-color: transparent;
  cursor: not-allowed;
  transform: none;
}

.btn[aria-pressed='true'] {
  background: var(--green-tint);
  border-color: var(--green-bright);
  color: var(--green-bright);
}

/* ------------------------------------------------------------
   Forms
   ------------------------------------------------------------ */

.field {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.field label {
  font-size: 13px;
  font-weight: 600;
  color: var(--fg-muted);
}

.input {
  height: 44px;
  padding: 0 18px;
  border: 1px solid transparent;
  border-radius: var(--pill);
  font-size: 15px;
  color: var(--fg);
  background: var(--surface-3);
  width: 100%;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.input::placeholder {
  color: var(--fg-faint);
}

.input:focus {
  outline: none;
  border-color: var(--fg);
}

/* ------------------------------------------------------------
   Hero / connect screen
   ------------------------------------------------------------ */

.hero {
  padding: 104px 0 56px;
  text-align: center;
}

.hero h1 {
  margin-bottom: 16px;
}

.hero .lede {
  margin: 0 auto 32px;
}

.cta-row {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}

.steps {
  list-style: none;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
  margin-top: 56px;
  text-align: left;
}

.steps li {
  background: var(--surface);
  border-radius: var(--radius);
  padding: 20px;
}

.step-k {
  display: block;
  font-weight: 800;
  font-size: 12px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--green-bright);
  margin-bottom: 8px;
}

.steps p {
  font-size: 15px;
  color: var(--fg-muted);
  line-height: 1.55;
}

.note-card {
  margin: 40px auto 0;
  max-width: 760px;
  text-align: left;
  background: var(--green-tint);
  border: 1px solid rgba(30, 215, 96, 0.3);
  border-radius: var(--radius);
  padding: 18px 24px;
}

.note-card p {
  font-size: 14px;
  color: var(--fg);
  line-height: 1.6;
}

.note-card p + p {
  margin-top: 8px;
}

.setup-card {
  margin: 48px auto 0;
  max-width: 760px;
  text-align: left;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 28px;
}

.setup-card h2 {
  font-size: 22px;
  margin-bottom: 8px;
}

.setup-card > p {
  font-size: 15px;
  color: var(--fg-muted);
  margin-bottom: 20px;
}

.setup-ol {
  margin: 0 0 24px;
  padding-left: 20px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  font-size: 15px;
  color: var(--fg-muted);
}

.setup-ol a {
  color: var(--green-bright);
  font-weight: 600;
}

.setup-ol a:hover {
  text-decoration: underline;
}

.setup-form {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.setup-form .btn {
  align-self: flex-start;
}

.form-error {
  font-size: 14px;
  color: #f87171;
}

/* ------------------------------------------------------------
   Library
   ------------------------------------------------------------ */

.page {
  padding: 0 0 0;
}

.page-hero {
  padding: 104px 0 24px;
}

.page-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  margin-bottom: 28px;
}

.search-row {
  display: flex;
  gap: 12px;
  margin-bottom: 28px;
  flex-wrap: wrap;
}

.search-row .input {
  flex: 1;
  min-width: 220px;
}

.segmented {
  display: inline-flex;
  gap: 4px;
  padding: 4px;
  background: var(--surface-2);
  border-radius: var(--pill);
}

.seg-btn {
  height: 40px;
  padding: 0 18px;
  font-size: 14px;
  font-weight: 700;
  color: var(--fg-muted);
  border-radius: var(--pill);
  transition: background 0.2s ease, color 0.2s ease;
}

.seg-btn:hover {
  color: var(--fg);
}

.seg-btn.active {
  background: var(--fg);
  color: #000;
}

.playlist-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}

.playlist-card {
  text-align: left;
  background: var(--surface);
  border: none;
  border-radius: var(--radius);
  padding: 14px;
  transition: background 0.25s ease, transform 0.25s ease;
}

.playlist-card:hover {
  background: var(--surface-hover);
}

.playlist-art {
  width: 100%;
  aspect-ratio: 1 / 1;
  object-fit: cover;
  border-radius: var(--radius);
  background: var(--surface-2);
  box-shadow: var(--shadow-card);
}

.art-fallback {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--surface-2);
  color: var(--fg-faint);
  font-size: 13px;
  font-weight: 500;
}

.playlist-card .art-fallback {
  aspect-ratio: 1 / 1;
}

.playlist-card-body {
  padding-top: 12px;
}

.playlist-card-body h3 {
  font-family: var(--font);
  font-weight: 700;
  font-size: 15px;
  line-height: 1.35;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.playlist-card-body .meta {
  font-size: 13px;
  color: var(--fg-muted);
  margin-top: 2px;
}

.back-link {
  display: inline-flex;
  align-items: center;
  height: 44px;
  font-size: 14px;
  font-weight: 700;
  color: var(--fg-muted);
  margin-bottom: 12px;
}

.back-link:hover {
  color: var(--fg);
}

.playlist-head {
  display: flex;
  align-items: flex-end;
  gap: 24px;
  margin-bottom: 28px;
}

.playlist-head img,
.playlist-head .art-fallback {
  width: 132px;
  height: 132px;
  border-radius: var(--radius);
  object-fit: cover;
  flex-shrink: 0;
  box-shadow: var(--shadow-card);
}

.playlist-head .art-fallback {
  aspect-ratio: auto;
}

.playlist-head h2 {
  font-size: clamp(28px, 5vw, 48px);
  font-weight: 800;
  letter-spacing: -0.02em;
}

.track-list {
  border-top: 1px solid var(--border);
}

.track-row {
  display: grid;
  grid-template-columns: 28px 48px 1fr auto auto;
  gap: 16px;
  align-items: center;
  padding: 10px 12px;
  border-radius: var(--radius);
}

.track-row:hover {
  background: rgba(255, 255, 255, 0.1);
}

.track-idx {
  font-size: 14px;
  color: var(--fg-muted);
  font-variant-numeric: tabular-nums;
  text-align: right;
}

.track-thumb {
  width: 48px;
  height: 48px;
  border-radius: 6px;
  object-fit: cover;
  background: var(--surface-2);
}

.track-thumb.art-fallback {
  font-size: 10px;
  border-radius: 6px;
}

.track-main {
  min-width: 0;
}

.track-name {
  font-size: 15px;
  font-weight: 600;
  line-height: 1.3;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.track-artists {
  font-size: 13px;
  color: var(--fg-muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.track-duration {
  font-size: 14px;
  color: var(--fg-muted);
  font-variant-numeric: tabular-nums;
}

.track-row .btn-small {
  background: var(--green);
  color: #000;
  border: none;
}

.track-row .btn-small:hover {
  background: var(--green-bright);
}

.banner {
  display: flex;
  gap: 10px;
  align-items: baseline;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 14px 18px;
  font-size: 14px;
  color: var(--fg-muted);
  margin-bottom: 20px;
}

.banner-warn {
  background: rgba(255, 180, 0, 0.08);
  border-color: rgba(255, 180, 0, 0.35);
  color: #ffd27d;
}

.banner-info {
  background: var(--green-tint);
  border-color: rgba(30, 215, 96, 0.3);
  color: var(--fg);
}

.empty-state {
  padding: 64px 0;
  text-align: center;
}

.empty-state p {
  margin-top: 8px;
  color: var(--fg-muted);
  font-size: 15px;
}

/* ------------------------------------------------------------
   Room — the performance stage
   ------------------------------------------------------------ */

.room {
  min-height: 100vh;
  background: var(--bg);
  color: var(--fg);
  padding: 88px 24px 24px;
  display: flex;
  flex-direction: column;
  position: relative;
  overflow: hidden;
}

.room-glow {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 0;
}

.room :focus-visible {
  outline-color: var(--green-bright);
}

.room-inner {
  position: relative;
  z-index: 1;
  width: 100%;
  max-width: 980px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 18px;
  flex: 1;
  min-height: 0;
}

.room-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
}

.room-track {
  display: flex;
  align-items: center;
  gap: 14px;
  min-width: 0;
}

.room-track img,
.room-track .art-fallback {
  width: 64px;
  height: 64px;
  border-radius: var(--radius);
  object-fit: cover;
  background: var(--surface-2);
  box-shadow: var(--shadow-card);
  flex-shrink: 0;
}

.room-track .art-fallback {
  color: var(--fg-faint);
  font-size: 11px;
}

.room-track-text {
  min-width: 0;
}

.room-track-text strong {
  display: block;
  font-weight: 800;
  font-size: 18px;
  line-height: 1.3;
  letter-spacing: -0.01em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.room-track-text span {
  display: block;
  font-size: 13px;
  color: var(--fg-muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.room-next {
  font-size: 13px;
  color: var(--fg-faint);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.status-chip {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  border: 1px solid var(--border-strong);
  border-radius: var(--pill);
  padding: 9px 16px;
  font-size: 13px;
  font-weight: 700;
  white-space: nowrap;
  background: rgba(0, 0, 0, 0.35);
}

.status-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--fg-faint);
}

.status-dot.you {
  background: var(--green-bright);
  box-shadow: 0 0 0 4px rgba(30, 215, 96, 0.22);
}

.status-dot.paused {
  background: rgba(255, 255, 255, 0.25);
}

.btn-dark {
  height: 44px;
  padding: 0 20px;
  border: 1px solid var(--border-strong);
  border-radius: var(--pill);
  color: var(--fg);
  font-size: 14px;
  font-weight: 700;
  transition: background 0.2s ease, border-color 0.2s ease;
}

.btn-dark:hover {
  background: rgba(255, 255, 255, 0.12);
  border-color: var(--fg);
}

.btn-dark:disabled {
  opacity: 0.4;
  cursor: not-allowed;
  background: transparent;
}

.btn-dark[aria-pressed='true'] {
  background: var(--green-tint);
  border-color: var(--green-bright);
  color: var(--green-bright);
}

.lyrics-panel {
  flex: 1;
  min-height: 320px;
  border: 1px solid var(--border);
  border-radius: 12px;
  background: rgba(0, 0, 0, 0.35);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  position: relative;
}

.lyrics-scroll {
  position: absolute;
  inset: 0;
  overflow-y: auto;
  padding: 40px 24px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  gap: 18px;
  scrollbar-width: thin;
  scrollbar-color: rgba(255, 255, 255, 0.25) transparent;
}

.lyrics-scroll::-webkit-scrollbar {
  width: 8px;
}

.lyrics-scroll::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.2);
  border-radius: var(--pill);
}

.lyric-line {
  text-align: center;
  font-size: 18px;
  font-weight: 500;
  line-height: 1.45;
  color: var(--fg-muted);
  opacity: 0.55;
  transition: opacity 0.3s ease, color 0.3s ease;
  max-width: 60ch;
}

.lyric-line.active {
  font-weight: 800;
  font-size: 28px;
  color: var(--fg);
  opacity: 1;
}

.lyric-line.sung {
  opacity: 0.25;
}

.who {
  display: inline-block;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 2px 10px;
  border-radius: var(--pill);
  margin-right: 10px;
  vertical-align: 4px;
}

.who-you {
  background: rgba(30, 215, 96, 0.18);
  color: var(--green-bright);
}

.who-artist {
  background: rgba(255, 255, 255, 0.12);
  color: var(--fg-muted);
}

.lyrics-empty {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  gap: 8px;
  padding: 24px;
}

.lyrics-empty strong {
  font-weight: 700;
  font-size: 18px;
}

.lyrics-empty p {
  font-size: 14px;
  color: var(--fg-muted);
  max-width: 52ch;
}

.plain-lyrics {
  position: absolute;
  inset: 0;
  overflow-y: auto;
  padding: 40px 24px;
  white-space: pre-wrap;
  text-align: center;
  font-size: 17px;
  line-height: 1.9;
  color: var(--fg-muted);
}

.meter-row {
  display: flex;
  align-items: center;
  gap: 14px;
}

.meter-label {
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--fg-muted);
  white-space: nowrap;
}

.meter {
  flex: 1;
  height: 8px;
  border-radius: var(--pill);
  background: rgba(255, 255, 255, 0.14);
  overflow: hidden;
}

.meter-fill {
  height: 100%;
  width: 0%;
  border-radius: var(--pill);
  background: linear-gradient(90deg, var(--green), var(--green-bright));
}

.pitch {
  font-size: 13px;
  color: var(--fg-muted);
  font-variant-numeric: tabular-nums;
  min-width: 120px;
  text-align: right;
}

.progress-row {
  display: flex;
  align-items: center;
  gap: 12px;
}

.time {
  font-size: 13px;
  color: var(--fg-muted);
  font-variant-numeric: tabular-nums;
  min-width: 42px;
}

.progress {
  flex: 1;
  height: 8px;
  border-radius: var(--pill);
  background: rgba(255, 255, 255, 0.14);
  cursor: pointer;
  position: relative;
}

/* Extend the seek bar's hit area without changing its look. */
.progress::before {
  content: '';
  position: absolute;
  inset: -12px 0;
}

.progress-fill {
  height: 100%;
  border-radius: var(--pill);
  background: var(--green-bright);
  width: 0%;
  pointer-events: none;
}

.room-controls {
  border-top: 1px solid var(--border);
  padding-top: 18px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 14px 18px;
  flex-wrap: wrap;
}

.ctrl-group {
  display: flex;
  align-items: center;
  gap: 10px;
}

.segmented-dark {
  display: inline-flex;
  gap: 4px;
  padding: 4px;
  background: var(--surface-2);
  border-radius: var(--pill);
}

.seg-btn-dark {
  height: 40px;
  padding: 0 16px;
  font-size: 14px;
  font-weight: 700;
  color: var(--fg-muted);
  border-radius: var(--pill);
  transition: background 0.2s ease, color 0.2s ease;
}

.seg-btn-dark:hover {
  color: var(--fg);
}

.seg-btn-dark.active {
  background: var(--fg);
  color: #000;
}

.slider-group {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.slider-group label {
  font-size: 12px;
  font-weight: 700;
  color: var(--fg-muted);
}

.slider-group input[type='range'] {
  width: 150px;
  accent-color: var(--green-bright);
}

.session-stats {
  font-size: 13px;
  color: var(--fg-muted);
}

.session-stats strong {
  color: var(--green-bright);
  font-weight: 800;
}

.room-note {
  font-size: 13px;
  color: var(--fg-faint);
  text-align: center;
}

/* ------------------------------------------------------------
   Toasts
   ------------------------------------------------------------ */

.toast-root {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 100;
  display: flex;
  flex-direction: column;
  gap: 8px;
  width: min(92vw, 480px);
}

.toast {
  background: var(--surface-3);
  color: var(--fg);
  border: 1px solid rgba(255, 255, 255, 0.18);
  border-radius: var(--radius);
  padding: 12px 16px;
  font-size: 14px;
  line-height: 1.5;
  box-shadow: 0 16px 40px rgba(0, 0, 0, 0.6);
  animation: toast-in 0.25s ease;
}

.toast.error {
  border-color: rgba(248, 113, 113, 0.55);
}

@keyframes toast-in {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* ------------------------------------------------------------
   Footer
   ------------------------------------------------------------ */

.footer {
  border-top: 1px solid var(--border);
  margin-top: 72px;
}

.footer-inner {
  max-width: 1120px;
  margin: 0 auto;
  padding: 26px 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
  font-size: 13px;
  color: var(--fg-faint);
}

.footer a {
  color: var(--fg-muted);
}

.footer a:hover {
  color: var(--fg);
}

/* ------------------------------------------------------------
   Responsive
   ------------------------------------------------------------ */

@media (max-width: 1024px) {
  .playlist-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (max-width: 768px) {
  .container {
    padding-left: 20px;
    padding-right: 20px;
  }

  .hero {
    padding: 88px 0 40px;
  }

  .steps {
    grid-template-columns: 1fr;
    gap: 12px;
    margin-top: 44px;
  }

  .playlist-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 14px;
