Now restructure renderLibraryScreen and renderTracksScreen with the page-hero wrapper + tint. Current renderLibraryScreen:

```ts
export function renderLibraryScreen(): void {
  const content = el(
    'main',
    { class: 'page' },
    el(
      'div',
      { class: 'container' },
      el('div', { class: 'page-head' }, ...),
      el('div', { class: 'search-row' }, ...),
      el('div', { id: 'library-results' }, ...),
    ),
  );
  shell(content);
  ...
}
```

New:
```ts
const content = el(
  'main',
  { class: 'page' },
  el('div', { class: 'page-hero' },
    el('div', { class: 'container' },
      page-head, search-row,
    ),
  ),
  el('div', { class: 'container' }, el('div', { id: 'library-results' }, ...)),
);
```
Note getElementById('library-search') after shell — still works.

renderTracksScreen:
```ts
function renderTracksScreen(detail, tracks) {
  const hero = el('div', { class: 'page-hero' },
    el('div', { class: 'container' },
      back-link,
      detail ? playlist-head : loading empty-state,
    ),
  );
  const content = el('main', { class: 'page' }, hero,
    el('div', { class: 'container' },
      detail ? premiumBanner() : null,
      detail ? (tracks.length ? trackList(...) : empty) : null,
    ),
  );
  shell(content);
  if (detail) void applyHeaderTint(hero, detail.images);
}

async function applyHeaderTint(hero: HTMLElement, images) {
  const tint = await dominantTint(images?.[0]?.url);
  if (!tint) return;
  if (!hero.isConnected) return;
  hero.style.background = `linear-gradient(180deg, rgb(${tint.r}, ${tint.g}, ${tint.b}) 0%, rgba(18,18,18,0.4) 72%, #121212 100%)`;
}
```

Also library screen keeps page-hero neutral. Let me apply edits.

